#include <iostream>
using namespace std;

// 函数重载示例
int add(int a, int b) {
    return a + b;
}

double add(double a, double b) {
    return a + b;
}

// 引用传递
void swap(int& x, int& y) {
    int temp = x;
    x = y;
    y = temp;
}

// 默认参数
void greet(string name, string prefix = "Hello") {
    cout << prefix << ", " << name << "!" << endl;
}

int main() {
    cout << add(3, 5) << endl;           // 整数加法
    cout << add(1.5, 2.5) << endl;       // 浮点加法

    int x = 10, y = 20;
    swap(x, y);                          // 引用传递
    cout << x << " " << y << endl;       // 20 10

    greet("Alice");                      // 默认参数
    greet("Bob", "Hi");                 // 自定义前缀
    return 0;
}

